/**
 * A connected link to one Mac.
 */
public protocol LinkHandleProtocol: AnyObject, Sendable {
    
    /**
     * Close the link and its transport. The signaling socket stays warm
     * for the next dial (`reset_warm_state` closes it).
     */
    func close() 
    
