#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLinkHandle: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = LinkHandle

    public static func lift(_ handle: UInt64) throws -> LinkHandle {
        return LinkHandle(unsafeFromHandle: handle)
    }

    public static func lower(_ value: LinkHandle) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LinkHandle {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: LinkHandle, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


