// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Link state events, in order: `Connecting`, then `Connected` (or
 * `Disconnected` when the dial fails), then any number of `PathChanged`,
 * `Rtt`, `Media` and `Suspect`, then one `Disconnected`.
 */

public enum LinkEvent: Equatable, Hashable {
    
    case connecting(transport: Transport
    )
    case connected(transport: Transport, path: LinkPath
    )
    case pathChanged(path: LinkPath
    )
    case rtt(millis: UInt32
    )
    /**
     * The WebRTC media session beside a WireGuard link changed.
     */
    case media(state: MediaState
    )
    case disconnected(reason: String
    )
    /**
     * The link heard nothing for `silent_millis` after a ping
     * (`Link::suspect_state`): a dead or silent Mac, a dead network, a
     * blackout. The link stays open and probes every second; the next
     * `Rtt` says it answered again, and it closes (`Disconnected`) only
     * after its keepalive timeout (45 s), so a blackout it survives keeps
     * the session. Last in the enum so the other variants keep their
     * numbers in the bindings.
     */
    case suspect(silentMillis: UInt32
    )





}

#if compiler(>=6)
extension LinkEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLinkEvent: FfiConverterRustBuffer {
    typealias SwiftType = LinkEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LinkEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connecting(transport: try FfiConverterTypeTransport.read(from: &buf)
        )
        
        case 2: return .connected(transport: try FfiConverterTypeTransport.read(from: &buf), path: try FfiConverterTypeLinkPath.read(from: &buf)
        )
        
        case 3: return .pathChanged(path: try FfiConverterTypeLinkPath.read(from: &buf)
        )
        
        case 4: return .rtt(millis: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .media(state: try FfiConverterTypeMediaState.read(from: &buf)
        )
        
        case 6: return .disconnected(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .suspect(silentMillis: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LinkEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .connecting(transport):
            writeInt(&buf, Int32(1))
            FfiConverterTypeTransport.write(transport, into: &buf)
            
        
        case let .connected(transport,path):
            writeInt(&buf, Int32(2))
            FfiConverterTypeTransport.write(transport, into: &buf)
            FfiConverterTypeLinkPath.write(path, into: &buf)
            
        
        case let .pathChanged(path):
            writeInt(&buf, Int32(3))
            FfiConverterTypeLinkPath.write(path, into: &buf)
            
        
        case let .rtt(millis):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(millis, into: &buf)
            
        
        case let .media(state):
            writeInt(&buf, Int32(5))
            FfiConverterTypeMediaState.write(state, into: &buf)
            
        
        case let .disconnected(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .suspect(silentMillis):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(silentMillis, into: &buf)
            
        }
    }
}


